import { createReadStream } from "node:fs"
import { copyFile, mkdir, readFile, rm, stat } from "node:fs/promises"
import { join, resolve } from "node:path"
import { Readable } from "node:stream"
import { AwsClient } from "aws4fetch"
import { Config, Context, Data, Effect, Layer, Option, Redacted } from "effect"

export class StorageError extends Data.TaggedError("StorageError")<{ readonly cause: unknown }> {}

/** Keys are generated by the app; anything else is refused before it reaches a path or URL. */
const validKey = /^[A-Za-z0-9][A-Za-z0-9-]{0,127}$/

const attempt = <A>(run: () => Promise<A>) =>
  Effect.tryPromise({ try: run, catch: (cause) => new StorageError({ cause }) })

const checked = <A>(key: string, run: () => Promise<A>) =>
  validKey.test(key)
    ? attempt(run)
    : Effect.fail(new StorageError({ cause: new Error("Invalid storage key") }))

export interface StorageSource {
  /** A local file to copy from, such as a persisted multipart upload. */
  readonly path: string
  readonly contentType: string
}

/** Blob storage for uploaded files. Metadata and authorization belong to the caller. */
export class Storage extends Context.Service<
  Storage,
  {
    readonly put: (key: string, source: StorageSource) => Effect.Effect<void, StorageError>
    /** `None` when no object exists under `key`. */
    readonly get: (
      key: string,
    ) => Effect.Effect<Option.Option<ReadableStream<Uint8Array>>, StorageError>
    /** Succeeds when the object is already gone. */
    readonly remove: (key: string) => Effect.Effect<void, StorageError>
  }
>()("server/Storage") {
  /** One file per key under `root`. Back it up with the database. */
  static readonly local = (root: string) =>
    Storage.of({
      put: (key, source) =>
        checked(key, async () => {
          await mkdir(root, { recursive: true })
          await copyFile(source.path, join(root, key))
        }),
      get: (key) =>
        checked(key, async () => {
          const path = join(root, key)
          const exists = await stat(path).then(
            (info) => info.isFile(),
            () => false,
          )
          if (!exists) return Option.none()
          return Option.some(
            Readable.toWeb(createReadStream(path)) as unknown as ReadableStream<Uint8Array>,
          )
        }),
      remove: (key) => checked(key, () => rm(join(root, key), { force: true })),
    })

  /** Path-style S3 API requests, so AWS, MinIO, R2, and similar services all work. */
  static readonly s3 = (options: {
    readonly endpoint: string
    readonly bucket: string
    readonly region: string
    readonly accessKeyId: string
    readonly secretAccessKey: string
  }) => {
    const client = new AwsClient({
      accessKeyId: options.accessKeyId,
      secretAccessKey: options.secretAccessKey,
      region: options.region,
      service: "s3",
      retries: 2,
    })
    const base = `${options.endpoint.replace(/\/+$/, "")}/${encodeURIComponent(options.bucket)}`
    const request = async (key: string, init: RequestInit) => {
      const response = await client.fetch(`${base}/${key}`, init)
      if (response.ok || (init.method !== "PUT" && response.status === 404)) return response
      await response.body?.cancel()
      throw new Error(`S3 ${init.method} failed with status ${response.status}`)
    }
    return Storage.of({
      put: (key, source) =>
        checked(key, async () => {
          const body = await readFile(source.path)
          const response = await request(key, {
            method: "PUT",
            body,
            headers: { "content-type": source.contentType },
          })
          await response.body?.cancel()
        }),
      get: (key) =>
        checked(key, async () => {
          const response = await request(key, { method: "GET" })
          if (response.status === 404 || response.body === null) {
            await response.body?.cancel()
            return Option.none()
          }
          return Option.some(response.body)
        }),
      remove: (key) =>
        checked(key, async () => {
          const response = await request(key, { method: "DELETE" })
          await response.body?.cancel()
        }),
    })
  }

  static readonly layer = Layer.effect(
    Storage,
    Effect.gen(function* () {
      const driver = yield* Config.Literals(["local", "s3"], "STORAGE_DRIVER").pipe(
        Config.withDefault("local"),
      )
      if (driver === "local") {
        const root = yield* Config.String("STORAGE_PATH").pipe(Config.withDefault("data/uploads"))
        return Storage.local(resolve(root))
      }
      const s3 = yield* Config.all({
        bucket: Config.NonEmptyString("S3_BUCKET"),
        region: Config.NonEmptyString("S3_REGION").pipe(Config.withDefault("us-east-1")),
        endpoint: Config.String("S3_ENDPOINT").pipe(Config.option),
        accessKeyId: Config.NonEmptyString("S3_ACCESS_KEY_ID"),
        secretAccessKey: Config.Redacted("S3_SECRET_ACCESS_KEY"),
      })
      return Storage.s3({
        bucket: s3.bucket,
        region: s3.region,
        endpoint: Option.getOrElse(s3.endpoint, () => `https://s3.${s3.region}.amazonaws.com`),
        accessKeyId: s3.accessKeyId,
        secretAccessKey: Redacted.value(s3.secretAccessKey),
      })
    }),
  )
}
